etadata -> 'title', 'null'::jsonb), '""'::jsonb) END, 'source_author', CASE WHEN COALESCE(d.author, '') ~ '\S' THEN to_jsonb(d.author) ELSE COALESCE(NULLIF(c.metadata -> 'source_author', 'null'::jsonb), '""'::jsonb) END, 'bib_doi', to_jsonb(d.bib_doi), 'bib_openalex_id', to_jsonb(d.bib_openalex_id), 'bib_semantic_scholar_id', to_jsonb(d.bib_semantic_scholar_id), 'content_type', to_jsonb(array_remove(ARRAY[ CASE WHEN d.content_type ~ '\S' THEN d.content_type END, f.fmt, CASE WHEN f.fmt IS NULL OR NOT (COALESCE(d.content_type, '') ~ '\S') THEN COALESCE(c.metadata ->> 'content_type', '') END ], NULL)) ) AS eff ) e WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND d.deleted_at IS NULL AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) ) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
GRANT EXECUTE ON FUNCTION nexus.catalog_source_format(text, text) TO nexus_svc;
DO $post$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname = 'catalog_source_format'; IF n <> 1 THEN RAISE EXCEPTION 'vectors-043-1: expected exactly 1 catalog_source_format function, found %', n; END IF; SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('manifest_search_384', 'manifest_search_768', 'manifest_search_1024') AND p.prosrc LIKE '%nexus.catalog_source_format(d.content_type, d.file_path)%'; IF n <> 3 THEN RAISE EXCEPTION 'vectors-043-1: expected the 3 manifest_search functions to call catalog_source_format, found %', n; END IF; END $post$;

